<?php
$statusTitle = match (PORTAL_ROLE) {
    'Extension Coordinator' => 'Extension Submission Status',
    'Research Coordinator' => 'Research Submission Status',
    default => 'Submission Status',
};
$user = portal_header($statusTitle, 'status');
if (PORTAL_ROLE === 'Research Coordinator') {
    $research = portal_research_projects();
    ?>
    <section class="panel"><div class="panel-heading"><h2>Research Submission Status</h2><label class="table-search"><span class="sr-only">Search research submissions</span><i class="ri-search-line"></i><input type="search" data-table-search="researchStatusTable" placeholder="Search research submissions"></label></div><div class="table-scroll"><table class="data-table" id="researchStatusTable" data-paginate="10"><thead><tr><th>Submission</th><th>Submitted By</th><th>Status</th><th>File</th><th>Review Feedback</th><th>Date</th><th>Timeline</th></tr></thead><tbody><?php foreach ($research as $row): ?><?php $remarks = trim((string) ($row['status_remarks'] ?? '')); $feedback = $remarks !== '' ? $remarks : ($row['status'] === 'Declined' ? 'No rejection reason was provided.' : ($row['status'] === 'Approved' ? 'No recommendation provided.' : 'No review remarks yet.')); ?><tr><td><?php echo h($row['title']); ?></td><td><?php echo h($row['fullname']); ?></td><td><span class="status-pill status-<?php echo h(statusClass($row['status'])); ?>"><?php echo h($row['status'] === 'Declined' ? 'Rejected' : $row['status']); ?></span></td><td><?php if (!empty($row['attachment_filename'])): ?><div class="file-actions"><a class="ghost-btn mini-btn" href="../uploads/records/<?php echo h($row['attachment_filename']); ?>" target="_blank" rel="noopener"><i class="ri-download-line"></i> File</a><button class="ghost-btn mini-btn" type="button" data-print-file="../uploads/records/<?php echo h($row['attachment_filename']); ?>"><i class="ri-printer-line"></i> Print</button></div><?php else: ?><span class="muted">None</span><?php endif; ?></td><td><button class="ghost-btn action-btn" type="button" data-open-modal="research-status-feedback-<?php echo (int) $row['id']; ?>"><i class="ri-chat-3-line"></i><span>View Feedback</span></button></td><td><?php echo h(date('M d, Y', strtotime($row['created_at']))); ?></td><td><details><summary>History</summary><div class="timeline-list"><?php foreach (review_timeline('research', (int) $row['id']) as $event): ?><div><strong><?php echo h($event['action']); ?></strong><p><?php echo h($event['remarks'] ?? ''); ?></p><small><?php echo h(($event['fullname'] ?? 'System') . ' | ' . date('M d, Y h:i A', strtotime($event['created_at']))); ?></small></div><?php endforeach; ?></div></details></td></tr><?php endforeach; ?><?php if (!$research): ?><tr data-pagination-empty><td colspan="7">No research submissions yet.</td></tr><?php endif; ?></tbody></table><p class="search-empty" data-search-empty="researchStatusTable" hidden>No matching research submissions.</p></div></section>
    <?php foreach ($research as $row): ?><?php $remarks = trim((string) ($row['status_remarks'] ?? '')); $feedback = $remarks !== '' ? $remarks : ($row['status'] === 'Declined' ? 'No rejection reason was provided.' : ($row['status'] === 'Approved' ? 'No recommendation provided.' : 'No review remarks yet.')); ?><div class="modal" id="research-status-feedback-<?php echo (int) $row['id']; ?>" aria-hidden="true"><div class="modal-backdrop" data-close-modal></div><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="research-status-title-<?php echo (int) $row['id']; ?>"><button class="modal-close" type="button" data-close-modal aria-label="Close"><i class="ri-close-line"></i></button><h2 id="research-status-title-<?php echo (int) $row['id']; ?>">Research Review Feedback</h2><p><strong><?php echo h($row['title']); ?></strong></p><p><span class="status-pill status-<?php echo h(statusClass($row['status'])); ?>"><?php echo h($row['status'] === 'Declined' ? 'Rejected' : $row['status']); ?></span></p><?php if ($row['status'] === 'Declined'): ?><p><strong>Rejection reason</strong></p><?php endif; ?><div class="feedback-content"><?php echo nl2br(h($feedback)); ?></div></div></div><?php endforeach; ?>
    <?php
    portal_footer();
    return;
}
if (PORTAL_ROLE === 'Extension Coordinator') {
    $extensions = portal_extension_projects();
    ?>
    <section class="panel"><div class="panel-heading"><h2>Extension Submission Status</h2><label class="table-search"><span class="sr-only">Search extension submissions</span><i class="ri-search-line"></i><input type="search" data-table-search="extensionStatusTable" placeholder="Search extension submissions"></label></div><div class="table-scroll"><table class="data-table" id="extensionStatusTable"><thead><tr><th>Submission</th><th>Submitted By</th><th>Status</th><th>File</th><th>Date</th></tr></thead><tbody><?php foreach ($extensions as $row): ?><tr><td><?php echo h($row['project_title']); ?></td><td><?php echo h($row['fullname']); ?></td><td><span class="status-pill status-<?php echo h(statusClass($row['progress_status'])); ?>"><?php echo h($row['progress_status']); ?></span></td><td><?php if (!empty($row['attachment_filename'])): ?><div class="file-actions"><a class="ghost-btn mini-btn" href="../uploads/records/<?php echo h($row['attachment_filename']); ?>" target="_blank" rel="noopener"><i class="ri-download-line"></i> File</a><button class="ghost-btn mini-btn" type="button" data-print-file="../uploads/records/<?php echo h($row['attachment_filename']); ?>"><i class="ri-printer-line"></i> Print</button></div><?php else: ?><span class="muted">None</span><?php endif; ?></td><td><?php echo h(date('M d, Y', strtotime($row['created_at']))); ?></td></tr><?php endforeach; ?><?php if (!$extensions): ?><tr><td colspan="5">No extension submissions yet.</td></tr><?php endif; ?></tbody></table><p class="search-empty" data-search-empty="extensionStatusTable" hidden>No matching extension submissions.</p></div></section>
    <section class="panel"><div class="panel-heading"><h2>Extension Review Timeline</h2></div><div class="timeline-list"><?php foreach ($extensions as $row): ?><details><summary><?php echo h($row['project_title']); ?> - <?php echo h($row['progress_status']); ?></summary><?php foreach (review_timeline('extension', (int) $row['id']) as $event): ?><div><strong><?php echo h($event['action']); ?></strong><p><?php echo h($event['remarks'] ?? ''); ?></p><small><?php echo h(($event['fullname'] ?? 'System') . ' | ' . date('M d, Y h:i A', strtotime($event['created_at']))); ?></small></div><?php endforeach; ?></details><?php endforeach; ?><?php if (!$extensions): ?><p>No extension history yet.</p><?php endif; ?></div></section>
    <?php
    portal_footer();
    return;
}
$research = portal_research_projects();
$documents = portal_documents();
?>
<section class="panel"><div class="panel-heading"><h2>Research Submission Status</h2><span>Pending | Under Review | Approved | Rejected</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Submission</th><th>Submitted By</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach ($research as $row): ?><tr><td><?php echo h($row['title']); ?></td><td><?php echo h($row['fullname']); ?></td><td><span class="status-pill status-<?php echo h(statusClass($row['status'])); ?>"><?php echo h($row['status'] === 'Declined' ? 'Rejected' : $row['status']); ?></span></td><td><?php echo h(date('M d, Y', strtotime($row['created_at']))); ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h2>Supporting Document Status</h2></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Document</th><th>Uploaded By</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach ($documents as $row): ?><tr><td><?php echo h($row['title']); ?></td><td><?php echo h($row['fullname']); ?></td><td><span class="status-pill status-<?php echo h(statusClass($row['status'])); ?>"><?php echo h($row['status'] === 'Declined' ? 'Rejected' : $row['status']); ?></span></td><td><?php echo h(date('M d, Y', strtotime($row['created_at']))); ?></td></tr><?php endforeach; ?></tbody></table></div></section>
